CREATE TABLE [purchase].[PurchaseReturns]([PurchaseReturnId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_PurchaseReturns_Id] DEFAULT NEWSEQUENTIALID(),[ReturnNumber] NVARCHAR(50) NOT NULL,[PurchaseInvoiceId] UNIQUEIDENTIFIER NOT NULL,[PurchaseItemId] UNIQUEIDENTIFIER NOT NULL,[Quantity] DECIMAL(18,4) NOT NULL,[AdjustmentAmount] DECIMAL(18,2) NOT NULL,[Reason] NVARCHAR(250) NOT NULL,[ReturnDate] DATETIMEOFFSET NOT NULL CONSTRAINT [DF_PurchaseReturns_Date] DEFAULT SYSUTCDATETIME(),[CreatedBy] NVARCHAR(256) NULL,[CreatedOn] DATETIMEOFFSET NOT NULL CONSTRAINT [DF_PurchaseReturns_Created] DEFAULT SYSUTCDATETIME(),CONSTRAINT [PK_PurchaseReturns] PRIMARY KEY([PurchaseReturnId]),CONSTRAINT [UQ_PurchaseReturns_Number] UNIQUE([ReturnNumber]),CONSTRAINT [FK_PurchaseReturns_Invoice] FOREIGN KEY([PurchaseInvoiceId]) REFERENCES [purchase].[PurchaseInvoices]([PurchaseInvoiceId]),CONSTRAINT [FK_PurchaseReturns_Item] FOREIGN KEY([PurchaseItemId]) REFERENCES [purchase].[PurchaseInvoiceItems]([PurchaseItemId]),CONSTRAINT [CK_PurchaseReturns_Quantity] CHECK([Quantity]>0));
GO
CREATE INDEX [IX_PurchaseReturns_Invoice] ON [purchase].[PurchaseReturns]([PurchaseInvoiceId],[ReturnDate]);
